package com.moinmalik.routine; import android.app.*; import android.os.*; import android.media.*; import android.view.*; import android.widget.*; import org.json.*;
public class AlarmActivity extends Activity { ToneGenerator tone; public void onCreate(Bundle b){ super.onCreate(b); if(Build.VERSION.SDK_INT>=27)setShowWhenLocked(true); getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON|WindowManager.LayoutParams.FLAG_TURN_SCREEN_ON); LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(48,80,48,48); try{ JSONObject s=new JSONObject(getIntent().getStringExtra("spec")); TextView title=new TextView(this);title.setText(s.optString("label","Routine alarm"));title.setTextSize(30);box.addView(title);TextView city=new TextView(this);city.setText(s.optString("prayerName")+" "+s.optString("city"));box.addView(city);Button stop=new Button(this);stop.setText("Stop");stop.setOnClickListener(v->finish());box.addView(stop); if(s.optBoolean("snooze",true)){Button snooze=new Button(this);snooze.setText("Snooze");snooze.setOnClickListener(v->{try{s.put("triggerAt",System.currentTimeMillis()+s.optInt("snoozeMinutes",10)*60000L);AlarmScheduler.schedule(this,s);}catch(Exception ignored){}finish();});box.addView(snooze);} if(!s.optString("sound").equals("silent-vibration")){tone=new ToneGenerator(AudioManager.STREAM_ALARM,90);tone.startTone(ToneGenerator.TONE_CDMA_ALERT_CALL_GUARD,10000);} }catch(Exception ignored){} setContentView(box); } protected void onDestroy(){if(tone!=null)tone.release();super.onDestroy();} }
